// next/image tạo nhiều kích thước ảnh và chọn kích thước vừa đủ cho màn hình
const deviceSizes = [640, 750, 828, 1080, 1200, 1920, 2048, 3840];   // mặc định của Next.js

function pickWidth(neededPx) {
  return deviceSizes.find((w) => w >= neededPx) ?? deviceSizes[deviceSizes.length - 1];
}

// Ảnh hiển thị rộng 400 CSS px trên màn hình DPR 2 cần 800 px thật => lấy bản 828
console.log(pickWidth(400 * 2));
console.log(pickWidth(1000));
console.log(pickWidth(5000));

// Giữ chỗ trước khi ảnh tải: tỷ lệ khung hình = height / width
const ratio = (w, h) => Math.round((h / w) * 10000) / 100;
console.log(ratio(1600, 900) + "%");

