const deviceSizes = [640, 750, 828, 1080, 1200, 1920, 2048, 3840];
function pickWidth(css, dpr) {
  const need = css * dpr;
  return deviceSizes.find((w) => w >= need) ?? deviceSizes[deviceSizes.length - 1];
}
console.log([pickWidth(300, 1), pickWidth(300, 2), pickWidth(1200, 2)].join(","));

